# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span


def make_shift(worker, day, start, end):
    return Shift(worker, day, Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("Ana", "mon", 540, 600),
            make_shift("Brisa", "mon", 540, 1020),
            make_shift("Brisa", "tue", 540, 810),
            make_shift("Ana", "tue", 540, 630),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 12.5 hours",
                "Ana: 2 shifts, 2.5 hours",
            ],
        )

    def test_one_decimal_place(self):
        shifts = [make_shift("Ana", "mon", 0, 20)]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Ana: 1 shifts, 0.3 hours"],
        )

    def test_ties_sorted_by_name(self):
        shifts = [
            make_shift("Zed", "mon", 540, 600),
            make_shift("Ana", "mon", 540, 600),
        ]
        lines = timesheet_lines(shifts)
        self.assertTrue(lines[0].startswith("Ana"))

    def test_accepts_any_iterable(self):
        shifts = (make_shift("Ana", "mon", 0, 60),)
        self.assertEqual(len(timesheet_lines(shifts)), 1)

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        for blank in ("", "   "):
            shifts = [
                make_shift("Ana", "mon", 0, 60),
                make_shift(blank, "tue", 0, 60),
            ]
            with self.assertRaises(ValueError):
                timesheet_lines(shifts)
